def _backfill_is_safe(profile_cohort, supervision_cohorts, post_cohorts):
    if profile_cohort is None:
        return False
    supervision = set(supervision_cohorts)
    posts = set(post_cohorts)
    if len(supervision) > 1 or len(posts) > 1:
        return False
    if supervision and supervision != {profile_cohort}:
        return False
    if posts and posts != {profile_cohort}:
        return False
    if supervision and posts and supervision != posts:
        return False
    return True


